def can_brute(a):
    n=len(a); seen={0}; st=[0]
    while st:
        i=st.pop()
        if i>=n-1: return True
        for j in range(1, a[i]+1):
            ni=i+j
            if ni not in seen and ni < n:
                seen.add(ni); st.append(ni)
    return False

def canJump(a):
    far=0
    for i,x in enumerate(a):
        if i>far: return False
        far=max(far, i+x)
    return True
